def calcul_valeur_totale_o0(data):
    lines = re.findall(r'o0.*?(?=o1|@end)', data, re.DOTALL)[0].strip().split('\n')
    total = 0
    for line in lines[1:]:
        indent_level = len(line) - len(line.lstrip())
        if indent_level == 2:
            parts = line.strip().split()
            qty = int(parts[1])
            price = int(parts[2])
            options_total = 0
            i = 1
            while lines[lines.index(line) + i].strip().startswith('  '):
                option_line = lines[lines.index(line) + i].strip()
                option_parts = option_line.split()
                options_total += int(option_parts[1])
                i += 1
            total += qty * (price + options_total)
    return total

